arguments.command:
cd /workspace && python3 - <<'PY'
p='/workspace/submission/service.py'
s=open(p).read()
start=s.index('    def overbook(')
end=s.index('\n    def handle(',start)
new='''    def overbook(self, capacities, start, end, offered=()):
        """Return a valid integral overload witness in [start,end)."""
        usage = [0] * len(capacities)
        for l, r in offered:
            usage[l] += r
        events = {}
        for b in self.live.values():
            s, e = b['window']
            if e <= start or s >= end:
                continue
            if s <= start:
                for l, r in b['envelope']:
                    usage[l] += r
            else:
                events.setdefault(s, []).append((b['envelope'], 1))
            # An active booking must stop contributing at its end.  Endpoints
            # are half-open, so checking after this event is checking the next
            # tick and is sufficient.
            if e < end:
                events.setdefault(e, []).append((b['envelope'], -1))
        def bad(t):
            for l, u in enumerate(usage):
                if u > capacities[l]:
                    return l, t, u, capacities[l]
            return None
        hit = bad(start)
        if hit:
            return hit
        for t in sorted(events):
            for env, sign in events[t]:
                for l, r in env:
                    usage[l] += sign * r
            hit = bad(t)
            if hit:
                return hit
        return None
'''
open(p,'w').write(s[:start]+new+s[end:])
